"""Regression: `google_search` / `google_shopping` landing on Google's JS
redirect interstitial instead of the SERP.

Captured live 2026-08-28 (Camoufox, DE, `wait_until: domcontentloaded` --
the preset's OLD default): 91,619 bytes, HTTP 200, block heuristic silent,
final URL identical to the requested one. Re-derived directly from that
capture rather than trusted from a summary: stripping <script>/<style> and
reading <body> alone leaves exactly 82 characters of visible text --
"Klicke hier, wenn du nach einigen Sekunden nicht automatisch weitergeleitet
wirst." ("Click here if you aren't redirected automatically after a few
seconds") -- Google's own client-side "you need JavaScript enabled" bounce
page, not a captcha, not /sorry, not a consent wall. Zero #rso, zero <h3>,
zero div.tF2Cxc, zero /goto?url= anywhere in the 91,619-byte document.
google_shopping_camoufox reproduces the identical shell independently
(verified live 2026-08-28, DE, udm=28: 90,802 bytes, the same
`table,div,span,p{display:none}` marker, 0 #rso / div.PhALMc matches) --
same host, same navigation, same defect, not assumed from the search twin.

The fixture below is the REAL <head> + the REAL <noscript> shell verbatim
from the 2026-08-28 DE capture; the ~91 KB of obfuscated bootstrap JS that
follows is elided (it defines no element any preset selector could ever
match, so it cannot change any assertion here). Kept inline rather than
read from `.superpowers/sdd/.../captures/` because that directory is
`.git/info/exclude`d scratch, not shipped source -- a prior task in the same
batch already lost its evidence that way.

Root cause, settled 2026-08-28 (task 5): `wait_until: domcontentloaded`
returns before Google's client-side check redirects away from this shell.
Measured live: a single fetch with `wait_until: load` (no selector) leaves
the shell and resolves the redirect for real, landing on either the SERP
(#rso populated) or google.com/sorry (this proxy pool's exit failed
Google's JS check) -- `domcontentloaded` never observes either outcome, it
only ever sees the shell. Adding `wait_for_selector` on top (mirroring
`yandex_search`, which needed the same wait_until+wait_for_selector shape
for a different symptom -- results streaming in after first paint) makes a
GENUINELY-STUCK-ON-THE-SHELL outcome raise `selector_not_found: <selector>`
from the runner itself, which `is_selector_miss()` (src/queue/scrape_runner.py)
recognises as retry-worthy and rotates to a fresh proxy exit. A outcome that
instead lands on google.com/sorry is a SEPARATE mechanism, corrected in fix
round 1 below (see `redirected_to_block()`), not the same one: `wait_for_selector`
is never even called there, so it cannot be what raises `selector_not_found`
for that path.

FIX ROUND 1 (2026-08-28): a reviewer correction, folded in here so this
docstring stops repeating the mistake the shipped preset descriptions also
had to fix. `redirected_to_block()` (src/browser/runner.py:329,
src/browser/camoufox_runner.py:441) is checked BETWEEN `page.goto` and
`wait_for_selector`, in both runners. On a `/sorry` landing it returns True,
`wait_for_selector` is skipped entirely, and the block classifier sets
`blocked=True` with `"Captcha/block detected by heuristic"` -- rotation then
happens on `fetch_result.blocked` (src/queue/scrape_runner.py:646), never on
`is_selector_miss()`. `tests/browser/test_selector_timeout_classification.py`
already pins this. `is_selector_miss()` only ever fires for the OTHER
outcome: stuck on this shell with the URL unchanged, which is not a
recognised block endpoint, so the selector wait genuinely runs and times out.
"""
from __future__ import annotations

import pytest

import json

from src.extract.extractor import extract_fields
from src.presets.models import Preset
from src.presets.store import DEFAULT_BUILTIN_DIR

# Verbatim from the 2026-08-28 google_camoufox_de.html capture (head + the
# noscript shell); the trailing obfuscated bootstrap script is cut (see
# module docstring).
GOOGLE_JS_REDIRECT_INTERSTITIAL = (
    '<!DOCTYPE html><html lang="de"><head><title>Google Search</title>'
    "<style>body{background-color:var(--xhUGwc)}</style>"
    '<script nonce="">window.google = window.google || {};'
    "window.google.c = window.google.c || {cap:0};</script></head><body>"
    "<noscript><style>table,div,span,p{display:none}</style>"
    '<meta content="0;url=/httpservice/retry/enablejs?sei=HEuRasDtI7SDxc8P85np6QM" '
    'http-equiv="refresh"><div style="display:block">'
    '<a href="/httpservice/retry/enablejs?sei=HEuRasDtI7SDxc8P85np6QM">Klicke hier</a>, '
    "wenn du nach einigen Sekunden nicht automatisch weitergeleitet wirst.</div>"
    "</noscript></body></html>"
)


def _load(name: str) -> Preset:
    path = DEFAULT_BUILTIN_DIR / f"{name}.json"
    return Preset(**json.loads(path.read_text(encoding="utf-8")))


class TestInterstitialExtractsNoRows:
    """The shell has nothing for either preset\'s parser to find -- the same
    fixture proves it for both bases independently, which is what makes the
    wait-strategy fix (below) the thing that actually matters: a preset that
    stops here reports 0 rows with an error that never says why."""

    def test_google_search_yields_zero_rows(self):
        preset = _load("google_search_camoufox")
        data, warnings = extract_fields(
            GOOGLE_JS_REDIRECT_INTERSTITIAL, preset.parsing_instructions
        )
        assert data["titles"] == []
        assert data["links"] == []
        assert data["snippets"] == []
        assert data["result_blocks"] == []
        assert "field \'titles\': required selector not found" in warnings

    def test_google_shopping_yields_zero_rows(self):
        preset = _load("google_shopping_camoufox")
        data, warnings = extract_fields(
            GOOGLE_JS_REDIRECT_INTERSTITIAL, preset.parsing_instructions
        )
        assert data["titles"] == []
        assert data["prices"] == []
        assert data["merchants"] == []
        assert "field \'titles\': required selector not found" in warnings

    def test_fixture_is_the_real_shell_not_a_trivial_stand_in(self):
        """Fix round 1: `assert data["titles"] == []` above passes on ANY
        page lacking `#rso div.tF2Cxc` -- an empty `<html><body></body></html>`
        would pass it too, silently turning the fixture into documentation
        instead of an input. Pin the properties ONLY the real shell has, so
        swapping the fixture for a trivial stand-in fails loudly here."""
        assert "table,div,span,p{display:none}" in GOOGLE_JS_REDIRECT_INTERSTITIAL
        assert "Klicke hier" in GOOGLE_JS_REDIRECT_INTERSTITIAL
        assert 'id="rso"' not in GOOGLE_JS_REDIRECT_INTERSTITIAL
        assert "<h3" not in GOOGLE_JS_REDIRECT_INTERSTITIAL
        assert "tF2Cxc" not in GOOGLE_JS_REDIRECT_INTERSTITIAL


GOOGLE_SEARCH_BASES = ("google_search_chromium", "google_search_camoufox")
GOOGLE_SHOPPING_BASES = ("google_shopping_chromium", "google_shopping_camoufox")


class TestWaitStrategyWouldNotHaveStoppedOnTheInterstitial:
    """Pins the fix: `wait_until: domcontentloaded` with no `wait_for_selector`
    is exactly the configuration that captured the shell above. A preset that
    still carries it would stop on the same shell again; these assertions
    fail against that old configuration and pass against the fixed one."""

    def test_google_search_no_longer_stops_at_domcontentloaded(self):
        for name in GOOGLE_SEARCH_BASES:
            defaults = _load(name).request_defaults
            assert defaults.get("wait_until") == "load", name
            assert defaults.get("wait_for_selector") == "#rso", name

    def test_google_shopping_no_longer_stops_at_domcontentloaded(self):
        for name in GOOGLE_SHOPPING_BASES:
            defaults = _load(name).request_defaults
            assert defaults.get("wait_until") == "load", name
            assert defaults.get("wait_for_selector") == "div.PhALMc.bVO81.lLi9V", name


